       summary.textContent = "Agent Reasoning / Output Stream";
       currentReasoningContent = document.createElement("div");
       currentReasoningContent.className = "reasoning-content";

       currentReasoning.appendChild(summary);
       currentReasoning.appendChild(currentReasoningContent);
       currentAiMessage.appendChild(currentReasoning);
       // Automatically open if first reasoning block
       currentReasoning.open = true;
     }
     return currentReasoningContent;
   }

   ws.onopen = () => {
     createMessage("system", "Connected to agent.");
     loadHistory(); // Load on start
     loadConnectionStatus(); // Load connection info
+    loadProfileStatus(); // Load profile info
   };
   ws.onclose = () => createMessage("system", "Connection closed.");
   ws.onerror = () => createMessage("system", "Connection error.");

   ws.onmessage = (event) => {
     const msg = JSON.parse(event.data);

     if (msg.type === "transition") {
       const container = getOrCreateReasoning();
       container.textContent += `\n[transition] -> ${msg.node}`;
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       return;
     }

     if (msg.type === "token") {
       // Tokens are intermediate reasoning thoughts
       const container = getOrCreateReasoning();
       container.textContent += msg.text;
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       return;
     }

     if (msg.type === "interrupt") {
       if (currentReasoning) currentReasoning.open = false;
       currentAiMessage = null; 
       currentReasoning = null;
       currentReasoningContent = null;

       const sqlQuery = msg.payload?.[0]?.args?.query || "";

       const container = document.createElement("div");
       container.className = "interrupt-controls";

       const title = document.createElement("div");
       title.innerHTML = "<strong>SQL Review Requested:</strong>";
       container.appendChild(title);

       const textarea = document.createElement("textarea");
       textarea.className = "interrupt-textarea";
       textarea.rows = 8;
       textarea.value = sqlQuery;
       container.appendChild(textarea);

       const btnRow = document.createElement("div");
       btnRow.className = "interrupt-buttons";

       const acceptBtn = document.createElement("button");
       acceptBtn.textContent = "Accept";
       acceptBtn.onclick = () => {
         createMessage("user", "Accepted SQL");
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "accept" } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       const rejectBtn = document.createElement("button");
       rejectBtn.textContent = "Reject";
       rejectBtn.onclick = () => {
         createMessage("user", "Rejected SQL");
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "reject" } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       const editBtn = document.createElement("button");
       editBtn.textContent = "Submit Edit";
       editBtn.onclick = () => {
         const val = textarea.value.trim();
         createMessage("user", "Edited SQL");
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "edit", edited_query: val } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       const feedbackBtn = document.createElement("button");
       feedbackBtn.textContent = "Submit Feedback";
       feedbackBtn.onclick = () => {
         const val = textarea.value.trim();
         createMessage("user", `Feedback: ${val}`);
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "response", feedback: val } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       btnRow.append(acceptBtn, editBtn, feedbackBtn, rejectBtn);
       container.appendChild(btnRow);

       messagesDiv.appendChild(container);
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       return;
     }

     if (msg.type === "final") {
       if (currentReasoning) currentReasoning.open = false;

       let aiMsg = currentAiMessage;
       if (!aiMsg) {
         aiMsg = createMessage("ai", "");
       }

       if (msg.answer) {
         const answerDiv = document.createElement("div");
         answerDiv.innerHTML = marked.parse(msg.answer);
         aiMsg.appendChild(answerDiv);
       }

       if (msg.sql) {
         const sqlToggle = document.createElement("details");
         sqlToggle.className = "reasoning-block";
         const summary = document.createElement("summary");
         summary.textContent = "Executed SQL";
         const content = document.createElement("div");
         content.className = "msg-sql";
         content.textContent = msg.sql;
         sqlToggle.appendChild(summary);
         sqlToggle.appendChild(content);
         aiMsg.appendChild(sqlToggle);
       }

       if (msg.ask_result_confirmation) {
         addMemorySaveButton(aiMsg, lastQuestion, msg.sql, msg.db_output, msg.history_id, 0);
       }

       currentAiMessage = null;
       currentReasoning = null;
       currentReasoningContent = null;
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       loadHistory(); // Refresh history
       return;
     }

     if (msg.type === "error") {
       currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
       createMessage("system", `Error: ${msg.message}`);
       return;
     }

     if (msg.type === "done") {
       currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
     }
   };

   askBtn.addEventListener("click", () => {
     const question = questionInput.value.trim();
     if (!question) return;

     lastQuestion = question;
     createMessage("user", question);
     questionInput.value = "";

     currentAiMessage = null;
     currentReasoning = null;
     currentReasoningContent = null;

     ws.send(JSON.stringify({ type: "ask", question }));
   });

   // Handle Enter key (Shift+Enter for newline)
   questionInput.addEventListener("keydown", (e) => {
     if (e.key === "Enter" && !e.shiftKey) {
       e.preventDefault();
       askBtn.click();
     }
   });
 </script>
