</style>

<div class="app-container">
  <div class="sidebar" id="historySidebar">
    <div class="sidebar-header">
      <h3>Recent History</h3>
      <a href="/chat" class="new-chat-btn">+ New</a>
    </div>
    <div id="historyList"></div>
  </div>

  <div class="chat-layout">
    <div id="chatMessages" class="chat-messages">
      <div id="chatMessagesInner" class="chat-messages-inner"></div>
    </div>

    <div class="chat-controls-wrapper">
      <div class="chat-controls-container">
        <div class="chat-controls">
          <textarea id="question" rows="3" placeholder="Ask a question about your database..."></textarea>
          <button id="askBtn" type="button">Send</button>
        </div>
        <div class="chat-status" id="dbStatus" onclick="openConnectionModal()" title="Click to change connection">
          Connected to <strong id="dbNameStr" style="margin-left: 4px;">...</strong>
          <span id="dbDialectBadge" class="db-dialect-badge" style="background-color: #666;">...</span>
        </div>
      </div>
    </div>
  </div>
</div>

<!-- Connection Modal -->
<div id="connModal" class="modal-overlay" onclick="closeModal(event)">
  <div class="modal-content" onclick="event.stopPropagation()">
    <button class="modal-close" onclick="closeConnectionModal()">&times;</button>
    <h2 style="margin-top: 0;">Select Target Source</h2>

    <!-- Main Menu -->
    <div id="connMenu">
      <button class="conn-menu-btn" onclick="showForm('sqlite')">[1] SQLite file path</button>
      <button class="conn-menu-btn" onclick="showForm('docker')">[2] Docker auto discovery</button>
      <button class="conn-menu-btn" onclick="showForm('uri')">[3] Direct SQLAlchemy URI</button>
    </div>

    <!-- SQLite Form -->
    <div id="formSqlite" class="conn-form">
      <button class="back-btn" onclick="showMenu()">&larr; Back</button>
      <label>SQLite File Path:</label>
      <input type="text" id="sqliteInput" placeholder="/path/to/db.sqlite">
      <button onclick="submitConnection('sqlite_path', document.getElementById('sqliteInput').value)">Connect</button>
    </div>

    <!-- Docker Form -->
    <div id="formDocker" class="conn-form">
      <button class="back-btn" onclick="showMenu()">&larr; Back</button>
      <div id="dockerLoading" class="loading-msg">Scanning for containers...</div>
      <div id="dockerList"></div>
    </div>

    <!-- Direct URI Form -->
    <div id="formUri" class="conn-form">
      <button class="back-btn" onclick="showMenu()">&larr; Back</button>
      <label>SQLAlchemy URI:</label>
      <input type="text" id="uriInput" placeholder="postgresql://user:pass@localhost:5432/db">
      <button onclick="submitConnection('direct_uri', document.getElementById('uriInput').value)">Connect</button>
    </div>
  </div>
</div>

<script>
  const messagesWrapper = document.getElementById("chatMessages");
  const messagesDiv = document.getElementById("chatMessagesInner");
  const askBtn = document.getElementById("askBtn");
  const questionInput = document.getElementById("question");
  const sidebar = document.getElementById("historySidebar");
  const historyList = document.getElementById("historyList");
  const sessionId = crypto.randomUUID();
  const protocol = location.protocol === "https:" ? "wss" : "ws";
  const ws = new WebSocket(`${protocol}://${location.host}/ws/chat/${sessionId}`);

  let currentAiMessage = null;
  let currentReasoning = null;
  let currentReasoningContent = null;
  let lastQuestion = "";

  // Modal Logic
  const connModal = document.getElementById("connModal");
  function openConnectionModal() {
    connModal.style.display = "flex";
    showMenu();
  }
  function closeConnectionModal() {
    connModal.style.display = "none";
  }
  function closeModal(e) {
    if (e.target === connModal) {
      closeConnectionModal();
    }
  }

  function hideAllForms() {
    document.getElementById("connMenu").style.display = "none";
    document.getElementById("formSqlite").style.display = "none";
    document.getElementById("formDocker").style.display = "none";
    document.getElementById("formUri").style.display = "none";
  }
  function showMenu() {
    hideAllForms();
    document.getElementById("connMenu").style.display = "block";
  }

  function showForm(type) {
    hideAllForms();
    if (type === 'sqlite') {
      document.getElementById("formSqlite").style.display = "flex";
      fetch('/api/connections')
        .then(res => res.json())
        .then(data => {
          if (data && data.default_sqlite_path) {
            document.getElementById("sqliteInput").placeholder = data.default_sqlite_path;
            if (!document.getElementById("sqliteInput").value) {
                document.getElementById("sqliteInput").value = data.default_sqlite_path;
            }
          }
        }).catch(() => {});
    } else if (type === 'uri') {
      document.getElementById("formUri").style.display = "flex";
    } else if (type === 'docker') {
      document.getElementById("formDocker").style.display = "flex";
      document.getElementById("dockerLoading").style.display = "block";
      document.getElementById("dockerList").innerHTML = "";

      fetch('/api/connections/docker')
        .then(res => res.json())
        .then(data => {
          document.getElementById("dockerLoading").style.display = "none";

          if (data.docker_status !== "available") {
            document.getElementById("dockerList").innerHTML = `<p style="color:red">Docker status: ${data.docker_status}</p>`;
            return;
          }

          const connectable = data.containers.filter(c => c.connectable && c.running);
          if (connectable.length === 0) {
            document.getElementById("dockerList").innerHTML = "<p>No supported running containers found.</p>";
            return;
          }

          let html = "";
          connectable.forEach((c, idx) => {
            html += `
              <div class="docker-item" onclick="activateDocker('${c.id}')">
                <strong>[${idx+1}] ${c.name}</strong><br>
                <small>type=${c.db_type} | host=${c.host} | port=${c.port||'-'} | db=${c.database||'-'}</small>
              </div>
            `;
          });
          document.getElementById("dockerList").innerHTML = html;
        })
        .catch(err => {
          document.getElementById("dockerLoading").style.display = "none";
          document.getElementById("dockerList").innerHTML = "<p>Error loading Docker containers.</p>";
        });
    }
  }

  async function submitConnection(mode, value) {
    if (!value) return;
    try {
      const res = await fetch('/api/connections', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({mode, value})
      });
      if (res.ok) {
        closeConnectionModal();
        loadConnectionStatus();
      } else {
        alert("Failed to change connection.");
      }
    } catch(err) {
      console.error(err);
      alert("Error changing connection.");
    }
  }

  async function activateDocker(container_id) {
    try {
      const res = await fetch(`/api/connections/docker/${container_id}/activate`, {
        method: 'POST'
      });
      if (res.ok) {
        closeConnectionModal();
        loadConnectionStatus();
      } else {
        alert("Failed to activate Docker connection.");
      }
    } catch(err) {
      console.error(err);
      alert("Error activating Docker connection.");
    }
  }

  // Load Connection Status
  async function loadConnectionStatus() {
    try {
      const res = await fetch('/api/connections');
      if (!res.ok) return;
      const data = await res.json();
      const activeUri = data.active_uri;
      if (!activeUri) return;

      const parts = activeUri.split("://");
      if (parts.length < 2) return;

      const fullDialect = parts[0];
      const dialect = fullDialect.split("+")[0].toLowerCase();
      let rest = parts[1];

      let dbName = "Unknown";
      if (dialect === "sqlite" || dialect === "duckdb") {
         let pathSegment = rest;
         if (rest.startsWith("///")) {
            pathSegment = rest.substring(3);
         } else if (rest.startsWith("//")) {
            pathSegment = rest.substring(2);
         } else if (rest.startsWith("/")) {
            pathSegment = rest.substring(1);
         }
         const segments = pathSegment.split("/");
         dbName = segments[segments.length - 1] || "db.sqlite";
      } else {
         const segments = rest.split("/");
         let potentialDb = segments[segments.length - 1];
         if (potentialDb.includes("?service_name=")) {
           dbName = potentialDb.split("?service_name=")[1];
         } else {
           dbName = potentialDb;
         }
      }

      document.getElementById("dbNameStr").textContent = dbName;

      const dialectEl = document.getElementById("dbDialectBadge");
      let badgeColor = "#555";
      let dialectLabel = dialect.toUpperCase();
      let textColor = "white";

      if (dialect === "postgresql" || dialect === "postgres") {
        dialectLabel = "Postgres";
        badgeColor = "#336791";
      } else if (dialect === "mysql" || dialect === "mariadb") {
        dialectLabel = "MySQL";
        badgeColor = "#00758F";
      } else if (dialect === "mssql") {
        dialectLabel = "MS SQL";
        badgeColor = "#CC292B";
      } else if (dialect === "sqlite") {
        dialectLabel = "SQLite";
        badgeColor = "#003B57";
      } else if (dialect === "oracle") {
        dialectLabel = "Oracle";
        badgeColor = "#F80000";
      } else if (dialect === "duckdb") {
        dialectLabel = "DuckDB";
        badgeColor = "#FFF000";
        textColor = "#000";
      }

      dialectEl.textContent = dialectLabel;
      dialectEl.style.backgroundColor = badgeColor;
      dialectEl.style.color = textColor;
    } catch(err) {
      console.error("Failed to load connection status", err);
    }
  }
  // Load History
  async function loadHistory() {
    try {
      const res = await fetch('/api/history');
      if (!res.ok) return;
      const data = await res.json();
      historyList.innerHTML = '';
      data.history.forEach(item => {
        const div = document.createElement('div');
        div.className = 'history-item';

        const date = new Date(item.created_at * 1000);
        const dateStr = date.toLocaleString();

        div.innerHTML = `
          <div class="history-item-content" onclick="renderHistoricalItem(this.parentElement.dataset.item)">
            <div class="history-date">${dateStr}</div>
            <div class="history-question" title="${item.question}">${item.question}</div>
          </div>
          <button class="history-delete-btn" title="Delete" onclick="deleteHistory(event, '${item.id}')">×</button>
        `;

        // Storing data object for the onclick handler
        div.dataset.item = JSON.stringify(item);

        // Handle rendering directly
        div.querySelector('.history-item-content').onclick = function(e) {
            renderHistoricalItem(JSON.parse(div.dataset.item));
        };

        historyList.appendChild(div);
      });
    } catch(err) {
      console.error("Failed to load history", err);
    }
  }

  async function deleteHistory(e, id) {
    e.stopPropagation();
    if (!confirm("Are you sure you want to delete this chat history entry?")) return;
    try {
      const res = await fetch(`/api/history/${id}`, { method: 'DELETE' });
      if (res.ok) {
        loadHistory();
      } else {
        alert("Failed to delete history item.");
      }
    } catch (err) {
      console.error("Failed to delete history", err);
    }
  }

  function renderHistoricalItem(item) {
    messagesDiv.innerHTML = ""; // clear current chat
    createMessage("user", item.question);

    const aiMsg = createMessage("ai", "");
    aiMsg.innerHTML = marked.parse(item.answer || "No answer generated.");

    if (item.sql) {
      const sqlToggle = document.createElement("details");
      sqlToggle.className = "reasoning-block";
      const summary = document.createElement("summary");
      summary.textContent = "Executed SQL";
      const content = document.createElement("div");
      content.className = "msg-sql";
      content.textContent = item.sql;
      sqlToggle.appendChild(summary);
      sqlToggle.appendChild(content);
      aiMsg.appendChild(sqlToggle);
    }

    addMemorySaveButton(aiMsg, item.question, item.sql, item.db_output, item.id, item.is_saved);
    messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
  }

  function addMemorySaveButton(parentDiv, question, sql, db_output, history_id, is_saved) {
    if (!sql) return;

    const container = document.createElement("div");
    container.className = "memory-btn-row";

    if (is_saved === 1) {
      container.innerHTML = `<span class="memory-saved-text">✔ Saved to Memory</span>`;
      parentDiv.appendChild(container);
      return;
    } else if (is_saved === -1) {
      // previously rejected, do not show anything
      return;
    }

    container.innerHTML = `<span>Was this correct?</span>`;

    const btnYes = document.createElement("button");
    btnYes.className = "memory-btn yes";
    btnYes.textContent = "✔";

    const btnNo = document.createElement("button");
    btnNo.className = "memory-btn no";
    btnNo.textContent = "✘";

    btnYes.onclick = async () => {
      btnYes.disabled = true;
      btnNo.disabled = true;
      container.innerHTML = `<span>Saving...</span>`;
      try {
        const res = await fetch("/api/memory/save", {
          method: "POST",
          headers: {"Content-Type": "application/json"},
          body: JSON.stringify({question, sql, db_output, history_id})
        });
        if (res.ok) {
          container.innerHTML = `<span class="memory-saved-text">✔ Saved to Memory</span>`;
          loadHistory(); // update the list
        } else {
          container.innerHTML = `<span>Failed to save</span>`;
        }
      } catch(e) {
        container.innerHTML = `<span>Error saving</span>`;
      }
    };

    btnNo.onclick = async () => {
      btnYes.disabled = true;
      btnNo.disabled = true;
      container.style.display = 'none'; // hide immediately
      if (history_id) {
        try {
          await fetch("/api/memory/reject", {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify({question, sql, db_output, history_id})
          });
          loadHistory(); // update the list
        } catch(e) {}
      }
    };

    container.appendChild(btnYes);
    container.appendChild(btnNo);
    parentDiv.appendChild(container);
  }

  function createMessage(type, content) {
    const div = document.createElement("div");
    div.className = `message msg-${type}`;
    if (type === 'user' || type === 'system') {
       div.textContent = content;
    } else if (content) {
       div.innerHTML = marked.parse(content);
    }
    messagesDiv.appendChild(div);
    messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
    return div;
  }

  function getOrCreateReasoning() {
    if (!currentAiMessage) {
      currentAiMessage = createMessage("ai", "");
    }
    if (!currentReasoning) {
      currentReasoning = document.createElement("details");
      currentReasoning.className = "reasoning-block";
      const summary = document.createElement("summary");
      summary.textContent = "Agent Reasoning / Output Stream";
      currentReasoningContent = document.createElement("div");
      currentReasoningContent.className = "reasoning-content";

      currentReasoning.appendChild(summary);
      currentReasoning.appendChild(currentReasoningContent);
      currentAiMessage.appendChild(currentReasoning);
      // Automatically open if first reasoning block
      currentReasoning.open = true;
    }
    return currentReasoningContent;
  }

  ws.onopen = () => {
    createMessage("system", "Connected to agent.");
    loadHistory(); // Load on start
    loadConnectionStatus(); // Load connection info
  };
  ws.onclose = () => createMessage("system", "Connection closed.");
  ws.onerror = () => createMessage("system", "Connection error.");

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);

    if (msg.type === "transition") {
      const container = getOrCreateReasoning();
      container.textContent += `\n[transition] -> ${msg.node}`;
      messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
      return;
    }

    if (msg.type === "token") {
      // Tokens are intermediate reasoning thoughts
      const container = getOrCreateReasoning();
      container.textContent += msg.text;
      messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
      return;
    }

    if (msg.type === "interrupt") {
      if (currentReasoning) currentReasoning.open = false;
      currentAiMessage = null; 
      currentReasoning = null;
      currentReasoningContent = null;

      const sqlQuery = msg.payload?.[0]?.args?.query || "";

      const container = document.createElement("div");
      container.className = "interrupt-controls";

      const title = document.createElement("div");
      title.innerHTML = "<strong>SQL Review Requested:</strong>";
      container.appendChild(title);

      const textarea = document.createElement("textarea");
      textarea.className = "interrupt-textarea";
      textarea.rows = 8;
      textarea.value = sqlQuery;
      container.appendChild(textarea);

      const btnRow = document.createElement("div");
      btnRow.className = "interrupt-buttons";

      const acceptBtn = document.createElement("button");
      acceptBtn.textContent = "Accept";
      acceptBtn.onclick = () => {
        createMessage("user", "Accepted SQL");
        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "accept" } }));
        currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
        container.remove();
      };

      const rejectBtn = document.createElement("button");
      rejectBtn.textContent = "Reject";
      rejectBtn.onclick = () => {
        createMessage("user", "Rejected SQL");
        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "reject" } }));
        currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
        container.remove();
      };

      const editBtn = document.createElement("button");
      editBtn.textContent = "Submit Edit";
      editBtn.onclick = () => {
        const val = textarea.value.trim();
        createMessage("user", "Edited SQL");
        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "edit", edited_query: val } }));
        currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
        container.remove();
      };

      const feedbackBtn = document.createElement("button");
      feedbackBtn.textContent = "Submit Feedback";
      feedbackBtn.onclick = () => {
        const val = textarea.value.trim();
        createMessage("user", `Feedback: ${val}`);
        ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "response", feedback: val } }));
        currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
        container.remove();
      };

      btnRow.append(acceptBtn, editBtn, feedbackBtn, rejectBtn);
      container.appendChild(btnRow);

      messagesDiv.appendChild(container);
      messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
      return;
    }

    if (msg.type === "final") {
      if (currentReasoning) currentReasoning.open = false;

      let aiMsg = currentAiMessage;
      if (!aiMsg) {
        aiMsg = createMessage("ai", "");
      }

      if (msg.answer) {
        const answerDiv = document.createElement("div");
        answerDiv.innerHTML = marked.parse(msg.answer);
        aiMsg.appendChild(answerDiv);
      }

      if (msg.sql) {
        const sqlToggle = document.createElement("details");
        sqlToggle.className = "reasoning-block";
        const summary = document.createElement("summary");
        summary.textContent = "Executed SQL";
        const content = document.createElement("div");
        content.className = "msg-sql";
        content.textContent = msg.sql;
        sqlToggle.appendChild(summary);
        sqlToggle.appendChild(content);
        aiMsg.appendChild(sqlToggle);
      }

      if (msg.ask_result_confirmation) {
        addMemorySaveButton(aiMsg, lastQuestion, msg.sql, msg.db_output, msg.history_id, 0);
      }

      currentAiMessage = null;
      currentReasoning = null;
      currentReasoningContent = null;
      messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
      loadHistory(); // Refresh history
      return;
    }

    if (msg.type === "error") {
      currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
      createMessage("system", `Error: ${msg.message}`);
      return;
    }

    if (msg.type === "done") {
      currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
    }
  };

  askBtn.addEventListener("click", () => {
    const question = questionInput.value.trim();
    if (!question) return;

    lastQuestion = question;
    createMessage("user", question);
    questionInput.value = "";

    currentAiMessage = null;
    currentReasoning = null;
    currentReasoningContent = null;

    ws.send(JSON.stringify({ type: "ask", question }));
  });

  // Handle Enter key (Shift+Enter for newline)
  questionInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      askBtn.click();
    }
  });
</script>
{% endblock %}

