 <script>
   const messagesWrapper = document.getElementById("chatMessages");
   const messagesDiv = document.getElementById("chatMessagesInner");
   const askBtn = document.getElementById("askBtn");
   const questionInput = document.getElementById("question");
   const sidebar = document.getElementById("historySidebar");
   const historyList = document.getElementById("historyList");
   const sessionId = crypto.randomUUID();
   const protocol = location.protocol === "https:" ? "wss" : "ws";
   const ws = new WebSocket(`${protocol}://${location.host}/ws/chat/${sessionId}`);

   let currentAiMessage = null;
   let currentReasoning = null;
   let currentReasoningContent = null;
   let lastQuestion = "";

   // Modal Logic
   const connModal = document.getElementById("connModal");
   function openConnectionModal() {
     connModal.style.display = "flex";
     showMenu();
   }
   function closeConnectionModal() {
     connModal.style.display = "none";
   }
   function closeModal(e) {
     if (e.target === connModal) {
       closeConnectionModal();
     }
   }

   // Profile Modal Logic
   const profileModal = document.getElementById("profileModal");
   function openProfileModal() {
     profileModal.style.display = "flex";
     loadProfiles();
   }
   function closeProfileModal(e) {
     if (e && e.target !== profileModal && e.target !== document.querySelector('#profileModal .modal-close')) return;
     profileModal.style.display = "none";
   }

   async function toggleContextLayer(enabled) {
     try {
       await fetch('/api/config/app', {
         method: 'PUT',
         headers: {'Content-Type': 'application/json'},
         body: JSON.stringify({ENABLE_CONTEXT_LAYER: enabled})
       });
     } catch(err) {
       console.error(err);
     }
   }

   async function selectProfile(profileName) {
     try {
       const isDefault = document.getElementById("saveProfileDefault").checked;
       const targetProfile = profileName || null;

       if (isDefault) {
         await fetch('/api/config/app', {
           method: 'PUT',
           headers: {'Content-Type': 'application/json'},
           body: JSON.stringify({CONTEXT_DEFAULT_SEMANTIC_PROFILE: targetProfile})
         });
       }
       await fetch('/api/context/reindex', {
         method: 'POST',
         headers: {'Content-Type': 'application/json'},
         body: JSON.stringify({semantic_profile: targetProfile})
       });
       document.getElementById("profileLabel").textContent = targetProfile || "No Profile Selected";
       closeProfileModal();
     } catch(err) {
       console.error(err);
     }
   }

   async function loadProfiles() {
     try {
       const res = await fetch('/api/context/profiles');
       const data = await res.json();
       let html = `<button class="conn-menu-btn" onclick="selectProfile('')"><em>None (No Profile)</em></button>`;
       data.profiles.forEach(p => {
         html += `<button class="conn-menu-btn" onclick="selectProfile('${p}')">${p}</button>`;
       });
       document.getElementById("profileMenu").innerHTML = html;
     } catch(err) {
       console.error(err);
     }
   }

   async function loadProfileStatus() {
     try {
       const res = await fetch('/api/config/app');
       const data = await res.json();
       const profile = data.CONTEXT_DEFAULT_SEMANTIC_PROFILE;
       document.getElementById("profileLabel").textContent = profile || "No Profile Selected";
       document.getElementById("contextToggle").checked = data.ENABLE_CONTEXT_LAYER;
     } catch(err) {
       console.error(err);
     }
   }

   function hideAllForms() {
     document.getElementById("connMenu").style.display = "none";
     document.getElementById("formSqlite").style.display = "none";
     document.getElementById("formDocker").style.display = "none";
     document.getElementById("formUri").style.display = "none";
   }
   function showMenu() {
     hideAllForms();
     document.getElementById("connMenu").style.display = "block";
   }

   function showForm(type) {
     hideAllForms();
     if (type === 'sqlite') {
       document.getElementById("formSqlite").style.display = "flex";
       fetch('/api/connections')
         .then(res => res.json())
         .then(data => {
           if (data && data.default_sqlite_path) {
             document.getElementById("sqliteInput").placeholder = data.default_sqlite_path;
             if (!document.getElementById("sqliteInput").value) {
                 document.getElementById("sqliteInput").value = data.default_sqlite_path;
             }
           }
         }).catch(() => {});
     } else if (type === 'uri') {
       document.getElementById("formUri").style.display = "flex";
     } else if (type === 'docker') {
       document.getElementById("formDocker").style.display = "flex";
       document.getElementById("dockerLoading").style.display = "block";
       document.getElementById("dockerList").innerHTML = "";

       fetch('/api/connections/docker')
         .then(res => res.json())
         .then(data => {
           document.getElementById("dockerLoading").style.display = "none";

           if (data.docker_status !== "available") {
             document.getElementById("dockerList").innerHTML = `<p style="color:red">Docker status: ${data.docker_status}</p>`;
             return;
           }

           const connectable = data.containers.filter(c => c.connectable && c.running);
           if (connectable.length === 0) {
             document.getElementById("dockerList").innerHTML = "<p>No supported running containers found.</p>";
             return;
           }

           let html = "";
           connectable.forEach((c, idx) => {
             html += `
               <div class="docker-item" onclick="activateDocker('${c.id}')">
                 <strong>[${idx+1}] ${c.name}</strong><br>
                 <small>type=${c.db_type} | host=${c.host} | port=${c.port||'-'} | db=${c.database||'-'}</small>
               </div>
             `;
           });
           document.getElementById("dockerList").innerHTML = html;
         })
         .catch(err => {
           document.getElementById("dockerLoading").style.display = "none";
           document.getElementById("dockerList").innerHTML = "<p>Error loading Docker containers.</p>";
         });
     }
   }

   async function submitConnection(mode, value) {
     if (!value) return;
     try {
       const res = await fetch('/api/connections', {
         method: 'POST',
         headers: {'Content-Type': 'application/json'},
         body: JSON.stringify({mode, value})
       });
       if (res.ok) {
         closeConnectionModal();
         loadConnectionStatus();
       } else {
         alert("Failed to change connection.");
       }
     } catch(err) {
       console.error(err);
       alert("Error changing connection.");
     }
   }

   async function activateDocker(container_id) {
     try {
       const res = await fetch(`/api/connections/docker/${container_id}/activate`, {
         method: 'POST'
       });
       if (res.ok) {
         closeConnectionModal();
         loadConnectionStatus();
       } else {
         alert("Failed to activate Docker connection.");
       }
     } catch(err) {
       console.error(err);
       alert("Error activating Docker connection.");
     }
   }

   // Load Connection Status
   async function loadConnectionStatus() {
     try {
       const res = await fetch('/api/connections');
       if (!res.ok) return;
       const data = await res.json();
       const activeUri = data.active_uri;
       if (!activeUri) return;

       const parts = activeUri.split("://");
       if (parts.length < 2) return;

       const fullDialect = parts[0];
       const dialect = fullDialect.split("+")[0].toLowerCase();
       let rest = parts[1];

       let dbName = "Unknown";
       if (dialect === "sqlite" || dialect === "duckdb") {
          let pathSegment = rest;
          if (rest.startsWith("///")) {
             pathSegment = rest.substring(3);
          } else if (rest.startsWith("//")) {
             pathSegment = rest.substring(2);
          } else if (rest.startsWith("/")) {
             pathSegment = rest.substring(1);
          }
          const segments = pathSegment.split("/");
          dbName = segments[segments.length - 1] || "db.sqlite";
       } else {
          const segments = rest.split("/");
          let potentialDb = segments[segments.length - 1];
          if (potentialDb.includes("?service_name=")) {
            dbName = potentialDb.split("?service_name=")[1];
          } else {
            dbName = potentialDb;
          }
       }

       document.getElementById("dbNameStr").textContent = dbName;

       const dialectEl = document.getElementById("dbDialectBadge");
       let badgeColor = "#555";
       let dialectLabel = dialect.toUpperCase();
       let textColor = "white";

       if (dialect === "postgresql" || dialect === "postgres") {
         dialectLabel = "Postgres";
         badgeColor = "#336791";
       } else if (dialect === "mysql" || dialect === "mariadb") {
         dialectLabel = "MySQL";
         badgeColor = "#00758F";
       } else if (dialect === "mssql") {
         dialectLabel = "MS SQL";
         badgeColor = "#CC292B";
       } else if (dialect === "sqlite") {
         dialectLabel = "SQLite";
         badgeColor = "#003B57";
       } else if (dialect === "oracle") {
         dialectLabel = "Oracle";
         badgeColor = "#F80000";
       } else if (dialect === "duckdb") {
         dialectLabel = "DuckDB";
         badgeColor = "#FFF000";
         textColor = "#000";
       }

       dialectEl.textContent = dialectLabel;
       dialectEl.style.backgroundColor = badgeColor;
       dialectEl.style.color = textColor;
     } catch(err) {
       console.error("Failed to load connection status", err);
     }
   }
   let allHistory = [];
