   // Load History
   async function loadHistory() {
     try {
       const res = await fetch('/api/history');
       if (!res.ok) return;
       const data = await res.json();
       allHistory = data.history;
       renderHistoryList(allHistory);
     } catch(err) {
       console.error("Failed to load history", err);
     }
   }

   function getDialectStyles(dialect) {
       let badgeColor = "#555";
       let dialectLabel = dialect ? dialect.toUpperCase() : "UNKNOWN";
       let textColor = "white";

       if (!dialect) return { badgeColor, dialectLabel, textColor };

       if (dialect === "postgresql" || dialect === "postgres") {
         dialectLabel = "Postgres";
         badgeColor = "#336791";
       } else if (dialect === "mysql" || dialect === "mariadb") {
         dialectLabel = "MySQL";
         badgeColor = "#00758F";
       } else if (dialect === "mssql") {
         dialectLabel = "MS SQL";
         badgeColor = "#CC292B";
       } else if (dialect === "sqlite") {
         dialectLabel = "SQLite";
         badgeColor = "#003B57";
       } else if (dialect === "oracle") {
         dialectLabel = "Oracle";
         badgeColor = "#F80000";
       } else if (dialect === "duckdb") {
         dialectLabel = "DuckDB";
         badgeColor = "#FFF000";
         textColor = "#000";
       }
       return { badgeColor, dialectLabel, textColor };
   }

   function renderHistoryList(historyArray) {
       historyList.innerHTML = '';
       historyArray.forEach(item => {
         const div = document.createElement('div');
         div.className = 'history-item';

         const date = new Date(item.created_at * 1000);
         const dateStr = date.toLocaleString();

         let dbHtml = "";
         if (item.db_name) {
             const styles = getDialectStyles(item.db_dialect);
             dbHtml = `<span style="font-size:0.7em; color:#666; margin-left:auto;">
               ${item.db_name}
               <span style="background-color:${styles.badgeColor}; color:${styles.textColor}; padding:2px 4px; border-radius:3px; margin-left:4px;">${styles.dialectLabel}</span>
             </span>`;
         }

         div.innerHTML = `
           <div class="history-item-content" onclick="renderHistoricalItem(this.parentElement.dataset.item)">
             <div style="display:flex; justify-content:space-between; align-items:center;">
               <div class="history-date">${dateStr}</div>
               ${dbHtml}
             </div>
             <div class="history-question" title="${item.question}">${item.question}</div>
           </div>
           <button class="history-delete-btn" title="Delete" onclick="deleteHistory(event, '${item.id}')">×</button>
         `;

         // Storing data object for the onclick handler
         div.dataset.item = JSON.stringify(item);

         // Handle rendering directly
         div.querySelector('.history-item-content').onclick = function(e) {
             renderHistoricalItem(JSON.parse(div.dataset.item));
         };

         historyList.appendChild(div);
       });
   }

   async function deleteHistory(e, id) {
     e.stopPropagation();
     if (!confirm("Are you sure you want to delete this chat history entry?")) return;
     try {
       const res = await fetch(`/api/history/${id}`, { method: 'DELETE' });
       if (res.ok) {
         loadHistory();
       } else {
         alert("Failed to delete history item.");
       }
     } catch (err) {
       console.error("Failed to delete history", err);
     }
   }

   function renderHistoricalItem(item) {
     messagesDiv.innerHTML = ""; // clear current chat
     createMessage("user", item.question);

     const aiMsg = createMessage("ai", "");
     aiMsg.innerHTML = marked.parse(item.answer || "No answer generated.");

     if (item.sql) {
       const sqlToggle = document.createElement("details");
       sqlToggle.className = "reasoning-block";
       const summary = document.createElement("summary");
       summary.textContent = "Executed SQL";
       const content = document.createElement("div");
       content.className = "msg-sql";
       content.textContent = item.sql;
       sqlToggle.appendChild(summary);
       sqlToggle.appendChild(content);
       aiMsg.appendChild(sqlToggle);
     }

     addMemorySaveButton(aiMsg, item.question, item.sql, item.db_output, item.id, item.is_saved);
     messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
   }

   function addMemorySaveButton(parentDiv, question, sql, db_output, history_id, is_saved) {
     if (!sql) return;

     const container = document.createElement("div");
     container.className = "memory-btn-row";

     if (is_saved === 1) {
       container.innerHTML = `<span class="memory-saved-text">✔ Saved to Memory</span>`;
       parentDiv.appendChild(container);
       return;
     } else if (is_saved === -1) {
       // previously rejected, do not show anything
       return;
     }

     container.innerHTML = `<span>Was this correct?</span>`;

     const btnYes = document.createElement("button");
     btnYes.className = "memory-btn yes";
     btnYes.textContent = "✔";

     const btnNo = document.createElement("button");
     btnNo.className = "memory-btn no";
     btnNo.textContent = "✘";

     btnYes.onclick = async () => {
       btnYes.disabled = true;
       btnNo.disabled = true;
       container.innerHTML = `<span>Saving...</span>`;
       try {
         const res = await fetch("/api/memory/save", {
           method: "POST",
           headers: {"Content-Type": "application/json"},
           body: JSON.stringify({question, sql, db_output, history_id})
         });
         if (res.ok) {
           container.innerHTML = `<span class="memory-saved-text">✔ Saved to Memory</span>`;
           loadHistory(); // update the list
         } else {
           container.innerHTML = `<span>Failed to save</span>`;
         }
       } catch(e) {
         container.innerHTML = `<span>Error saving</span>`;
       }
     };

     btnNo.onclick = async () => {
       btnYes.disabled = true;
       btnNo.disabled = true;
       container.style.display = 'none'; // hide immediately
       if (history_id) {
         try {
           await fetch("/api/memory/reject", {
             method: "POST",
             headers: {"Content-Type": "application/json"},
             body: JSON.stringify({question, sql, db_output, history_id})
           });
           loadHistory(); // update the list
         } catch(e) {}
       }
     };

     container.appendChild(btnYes);
     container.appendChild(btnNo);
     parentDiv.appendChild(container);
   }

   function createMessage(type, content) {
     const div = document.createElement("div");
     div.className = `message msg-${type}`;
     if (type === 'user' || type === 'system') {
        div.textContent = content;
     } else if (content) {
        div.innerHTML = marked.parse(content);
     }
     messagesDiv.appendChild(div);
     messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
     return div;
   }

   function getOrCreateReasoning() {
     if (!currentAiMessage) {
       currentAiMessage = createMessage("ai", "");
     }
     if (!currentReasoning) {
       currentReasoning = document.createElement("details");
       currentReasoning.className = "reasoning-block";
       const summary = document.createElement("summary");
       summary.textContent = "Agent Reasoning / Output Stream";
       currentReasoningContent = document.createElement("div");
       currentReasoningContent.className = "reasoning-content";

       currentReasoning.appendChild(summary);
       currentReasoning.appendChild(currentReasoningContent);
       currentAiMessage.appendChild(currentReasoning);
       // Automatically open if first reasoning block
       currentReasoning.open = true;
     }
     return currentReasoningContent;
   }

   ws.onopen = () => {
     createMessage("system", "Connected to agent.");
     loadHistory(); // Load on start
     loadConnectionStatus(); // Load connection info
     loadProfileStatus(); // Load profile info
   };
   ws.onclose = () => createMessage("system", "Connection closed.");
   ws.onerror = () => createMessage("system", "Connection error.");

   ws.onmessage = (event) => {
     const msg = JSON.parse(event.data);

     if (msg.type === "transition") {
       const container = getOrCreateReasoning();
       container.textContent += `\n[transition] -> ${msg.node}`;
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       return;
     }

     if (msg.type === "token") {
       // Tokens are intermediate reasoning thoughts
       const container = getOrCreateReasoning();
       container.textContent += msg.text;
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       return;
     }

     if (msg.type === "interrupt") {
       if (currentReasoning) currentReasoning.open = false;
       currentAiMessage = null; 
       currentReasoning = null;
       currentReasoningContent = null;

       const sqlQuery = msg.payload?.[0]?.args?.query || "";

       const container = document.createElement("div");
       container.className = "interrupt-controls";

       const title = document.createElement("div");
       title.innerHTML = "<strong>SQL Review Requested:</strong>";
       container.appendChild(title);

       const textarea = document.createElement("textarea");
       textarea.className = "interrupt-textarea";
       textarea.rows = 8;
       textarea.value = sqlQuery;
       container.appendChild(textarea);

       const btnRow = document.createElement("div");
       btnRow.className = "interrupt-buttons";

       const acceptBtn = document.createElement("button");
       acceptBtn.textContent = "Accept";
       acceptBtn.onclick = () => {
         createMessage("user", "Accepted SQL");
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "accept" } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       const rejectBtn = document.createElement("button");
       rejectBtn.textContent = "Reject";
       rejectBtn.onclick = () => {
         createMessage("user", "Rejected SQL");
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "reject" } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       const editBtn = document.createElement("button");
       editBtn.textContent = "Submit Edit";
       editBtn.onclick = () => {
         const val = textarea.value.trim();
         createMessage("user", "Edited SQL");
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "edit", edited_query: val } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       const feedbackBtn = document.createElement("button");
       feedbackBtn.textContent = "Submit Feedback";
       feedbackBtn.onclick = () => {
         const val = textarea.value.trim();
         createMessage("user", `Feedback: ${val}`);
         ws.send(JSON.stringify({ type: "interrupt_response", payload: { type: "response", feedback: val } }));
         currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
         container.remove();
       };

       btnRow.append(acceptBtn, editBtn, feedbackBtn, rejectBtn);
       container.appendChild(btnRow);

       messagesDiv.appendChild(container);
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       return;
     }

     if (msg.type === "final") {
       if (currentReasoning) currentReasoning.open = false;

       let aiMsg = currentAiMessage;
       if (!aiMsg) {
         aiMsg = createMessage("ai", "");
       }

       if (msg.answer) {
         const answerDiv = document.createElement("div");
         answerDiv.innerHTML = marked.parse(msg.answer);
         aiMsg.appendChild(answerDiv);
       }

       if (msg.sql) {
         const sqlToggle = document.createElement("details");
         sqlToggle.className = "reasoning-block";
         const summary = document.createElement("summary");
         summary.textContent = "Executed SQL";
         const content = document.createElement("div");
         content.className = "msg-sql";
         content.textContent = msg.sql;
         sqlToggle.appendChild(summary);
         sqlToggle.appendChild(content);
         aiMsg.appendChild(sqlToggle);
       }

       if (msg.ask_result_confirmation) {
         addMemorySaveButton(aiMsg, lastQuestion, msg.sql, msg.db_output, msg.history_id, 0);
       }

       currentAiMessage = null;
       currentReasoning = null;
       currentReasoningContent = null;
       messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
       loadHistory(); // Refresh history
       return;
     }

     if (msg.type === "error") {
       currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
       createMessage("system", `Error: ${msg.message}`);
       return;
     }

     if (msg.type === "done") {
       currentAiMessage = null; currentReasoning = null; currentReasoningContent = null;
     }
   };

   askBtn.addEventListener("click", () => {
     const question = questionInput.value.trim();
     if (!question) return;

     lastQuestion = question;
     createMessage("user", question);
     questionInput.value = "";

     currentAiMessage = null;
     currentReasoning = null;
     currentReasoningContent = null;

     ws.send(JSON.stringify({ type: "ask", question }));
   });

   // Handle Enter key (Shift+Enter for newline)
   questionInput.addEventListener("keydown", (e) => {
     if (e.key === "Enter" && !e.shiftKey) {
       e.preventDefault();
       askBtn.click();
