async function loadProfileStatus() {
  try {
    const res = await fetch('/api/config/app');
    const data = await res.json();

    // Load Profile
    const profile = data.CONTEXT_DEFAULT_SEMANTIC_PROFILE;
    document.getElementById("profileLabel").textContent = profile || "No Profile Selected";
    document.getElementById("contextToggle").checked = data.ENABLE_CONTEXT_LAYER;

    // Load Model Info
    const activeModel = data.LLM_ACTIVE_MODEL || "openai/gpt-oss-20b";
    document.getElementById("modelLabel").textContent = activeModel;

    let modelHtml = "";
    if (data.LLM_MODEL_LIST) {
        data.LLM_MODEL_LIST.forEach(m => {
          modelHtml += `<button class="conn-menu-btn" onclick="selectModel('${m}')">${m}</button>`;
        });
    }
    document.getElementById("modelMenu").innerHTML = modelHtml;

  } catch(err) {
    console.error(err);
  }
}

